```tsx
// src/components/ui/SegmentedControl.tsx
//
// A generic segmented control. Library owns appearance (variant/size/the
// canonical ink-on-paper active fill); consumer owns placement + data.
// No native <select>; this is a button group with roving radio semantics.

export interface SegmentOption<T extends string> {
  value: T;
  label: React.ReactNode;
  /** Disabled individual segment (e.g. Loupe with no sample selected). */
  disabled?: boolean;
  /** Per-segment title/tooltip (e.g. "Open a sample to use the loupe"). */
  title?: string;
  /** Stable test id for E2E, applied to the segment button. */
  testId?: string;
}

export type SegmentedVariant = "bordered" | "plain";
//  bordered — overflow-hidden rounded border wrapper, segments butt together
//             (ScaleToggle / RepresentationToggle / view-seg / folio sort).
//  plain    — no wrapper border, gap-1 between pill segments
//             (GroupingModeToggle, AnnotationToggles).

export type SegmentedSize = "sm" | "md";
//  sm — text-xs px-3 py-1.5 (current bordered toggles; padding bumped to meet
//       the 44px touch min via min-h, see below).
//  md — slightly larger for primary surfaces if needed.

export interface SegmentedControlProps<T extends string> {
  options: ReadonlyArray<SegmentOption<T>>;
  value: T;
  onChange: (next: T) => void;
  /** group | radiogroup — drives child role (button[aria-pressed] vs radio[aria-checked]). */
  role?: "group" | "radiogroup";
  variant?: SegmentedVariant;   // default "bordered"
  size?: SegmentedSize;         // default "sm"
  /** Required: names the control for AT (replaces today's inline aria-label). */
  "aria-label": string;
  /** Container test id (today's data-testid on the wrapper). */
  testId?: string;
  /** PLACEMENT-ONLY: margin / width / flex/grid position. No appearance utils. */
  className?: string;
}

export function SegmentedControl<T extends string>(
  props: SegmentedControlProps<T>,
): JSX.Element;
```
`className` is placement-only (e.g. `flex-1`, `ml-auto`, `w-full`). The guard bans appearance utilities (bg-/text-/border-color/rounded/px-/py-) in a consumer `className`. The container always reflects active value via `data-state={value}` (and segments via `data-active`/`data-value`) so E2E can assert without class strings.

```tsx
// src/components/ui/PhaseChip.tsx
import { phaseColor } from "../../phases";

type PhaseChipVariant = "tint" | "solid";
type PhaseChipSize = "sm" | "md";

interface PhaseChipProps
  extends Omit<React.HTMLAttributes<HTMLSpanElement>, "color" | "children"> {
  /** Phase name, e.g. "Pn3m". Rendered as the chip's text (the always-on
   *  second channel) AND drives the hue via phaseColor() internally. */
  phase: string;
  /** "tint": phase-tinted fill + phase-colored text (default, the M-6 look).
   *  "solid": phase-colored fill + paper text (for emphasis / dense rows). */
  variant?: PhaseChipVariant;
  /** "sm" = 11px mono (contact sheet, inline rows). "md" = 13px (candidate
   *  rows, builder). Default "sm". */
  size?: PhaseChipSize;
  /** PLACEMENT ONLY — margin / width / grid-or-flex position. Appearance
   *  utilities are banned by the guard. */
  className?: string;
}

export function PhaseChip({
  phase,
  variant = "tint",
  size = "sm",
  className = "",
  ...props
}: PhaseChipProps): JSX.Element;
```

Internals (closed look):
- `const color = phaseColor(phase)` — the recipe lives here, never in consumers.
- A `Record<PhaseChipSize, string>` sizeClass map ("sm" → `font-mono text-[11px] font-bold px-2 py-0.5`, "md" → `font-mono text-[13px] font-bold px-1.5 py-0.5`) joined with a base `inline-flex items-center rounded-sm border` and `${className}` appended last.
- variant drives `style`: tint → `{ color, background: color-mix(in oklab, ${color} 13%, transparent), borderColor: color-mix(in oklab, ${color} 35%, transparent) }`; solid → `{ color: "var(--color-paper)", background: color, borderColor: "transparent" }`.
- Always renders `{phase}` as text (the colour-blind second channel is non-negotiable, baked in — consumers cannot render a color-only chip).
- Carries `data-testid="phase-chip"` by default (overridable via spread) so existing SampleStatusChip selectors keep working.

`className` is appended after base+variant+size classes and is documented/guarded as placement-only.

```tsx
import { phaseColor } from "../../phases";

/** Normalized segment input both callers map into. One per series member,
 *  in display (low→high) order. `coexistWith` drives the 2-stop gradient;
 *  null phase = unindexed (renders the neutral ink-faint cell). */
export interface PhaseSegment {
  phase: string | null;
  coexistWith?: string | null;
}

export type PhaseStripSize = "sm" | "md"; // sm = legacy 8px Scoping bar; md = 7px folio bar (default)

export interface PhaseStripProps {
  segments: PhaseSegment[];
  size?: PhaseStripSize;                 // default "md"
  /** Optional kicker line above the strip (Scoping preview heading). */
  heading?: string;
  /** Copy when no segment is indexed. Default: "No clear phase". */
  emptyLabel?: string;
  /** PLACEMENT ONLY: margin / width / grid position. No appearance utilities. */
  className?: string;
}

export function PhaseStrip(props: PhaseStripProps): JSX.Element;
```

Notes:
- No `reads`/`members` in the API — both callers map their domain shape into `PhaseSegment[]` at the call site (Scoping maps `PhaseRead{dominant,coexist}` → `{phase:dominant, coexistWith:coexist}`; Series maps `buildPhaseStrip(members).segments` which is ALREADY `{phase, coexistWith}` — direct pass-through).
- Caption (first→last / "throughout" / empty) is derived INSIDE the primitive from `segments` (the same first-non-null / last-non-null / distinct-count logic `buildPhaseStrip` does today), so neither caller recomputes it.
- `className` appends after base+size classes (Button.tsx pattern) but is placement-only; appearance utilities banned by the Phase-0 guard.
- CHEAP second channel added NOW: each `<div data-testid=...>` segment gets `aria-label`/`title` naming its phase ("Pn3m", "Pn3m + Lamellar (coexistence)", or "Unindexed"). The VISUAL glyph/pattern second channel (hatching/shape per phase) is explicitly DEFERRED to the plotting redesign — boundary noted.

