// src/components/ui/Kicker.tsx
import type { HTMLAttributes } from "react";

export type KickerTone = "accent" | "faint";

interface KickerProps extends HTMLAttributes<HTMLElement> {
  /** terracotta page/section eyebrow vs. dim metric/field label. Default: "faint". */
  tone?: KickerTone;
  /**
   * Element to render. Section headings that introduce a region should be a
   * heading ("h2"/"h3") for the a11y tree; inline/aside labels stay "div"/"span".
   * Default: "div" (matches the prevailing inline usage).
   */
  as?: "div" | "span" | "h2" | "h3";
}

// tone overrides ONLY the color; geometry comes from the .text-label role.
const toneClass: Record<KickerTone, string> = {
  accent: "text-print-accent",
  faint: "text-ink-faint",
};

export function Kicker({
  tone = "faint",
  as: Tag = "div",
  className = "",
  children,
  ...props
}: KickerProps): JSX.Element {
  return (
    <Tag className={`text-label ${toneClass[tone]} ${className}`} {...props}>
      {children}
    </Tag>
  );
}
```
`className` is PLACEMENT-ONLY: margins (`mb-2`, `mb-1.5`, `mt-0.5`, `ml-auto`), block/inline (`block`), truncation/positioning for the rotated axis-title case (`absolute left-0 -rotate-90 …`). Appearance utilities (`uppercase`, `tracking-*`, `text-[Npx]`, `text-xs/sm`, `font-bold/semibold`, `text-print-accent`/`text-ink-faint`) are banned by the guard and must be dropped at every call site — color now flows through `tone`. SectionLabel is SUBSUMED: it becomes `Kicker({ as: "h3", tone: "faint", className: "mb-2" })` (or kept as a 1-line alias re-exporting Kicker for back-compat — see openQuestions).

