  align?: ModalAlign;          // default "center"
  /** Esc dismiss. Default true. Set false where the parent owns Escape (e.g. NavModal's input-scoped Backspace/Esc handler). */
  closeOnEsc?: boolean;
  /** Backdrop-click dismiss. Default true. */
  closeOnOutsideClick?: boolean;
  /** Drawer mode: skip the centering flex + scrim-as-frame-wrapper; render a right-edge sheet. Off by default. */
  variant?: "dialog" | "drawer"; // drawer -> fixed right-0 top-14 bottom-0 sheet (Notes drawer tier)
  /** a11y: at least one of these must be supplied by the caller. */
  "aria-label"?: string;
  "aria-labelledby"?: string;
  "aria-describedby"?: string;
  /** data-testid forwarded to the FRAME (role=dialog) element; scrim gets `${testId}-scrim`. */
  testId?: string;
  /** PLACEMENT-ONLY on the frame: max-height, extra width override, grid/flex of the *frame box*. No bg/border/radius/shadow. */
  className?: string;
  children: ReactNode;
}

export function ModalShell(props: ModalShellProps): JSX.Element | null;
```

`className` contract: appended LAST to the frame element, but allowed ONLY for placement (e.g. `max-h-[80vh]`, a one-off `w-[...]` when no size token fits, `flex flex-col`). Appearance utilities (`bg-*`, `border*`, `rounded*`, `shadow*`, `backdrop-*`) in a consumer `className` are banned by the Phase-3 guard — those come from `variant`/`size` internally. The scrim element is fully owned; consumers never style it.

```tsx
// ─── Card / Plate ────────────────────────────────────────────────
import type { HTMLAttributes } from "react";

interface CardProps extends HTMLAttributes<HTMLDivElement> {
  /** true → the single lifted "Plate Lift" object (inset highlight + soft
   *  warm drop shadow). false (default) → flat hairline card: tonal + hairline
   *  only, NO shadow (Flat-Except-the-Plate). */
  elevated?: boolean;
  /** hairline weight. "hair" (0.882, default) for inner cards;
   *  "strong" (0.806) for outer/standalone surfaces. */
  border?: "hair" | "strong";
  /** render as a different element (e.g. "section", "li") via discriminated
   *  union or polymorphic `as`; or keep it a div and let callers wrap. */
}

const borderClass: Record<NonNullable<CardProps["border"]>, string> = {
  hair: "border border-hair",
  strong: "border border-hair-strong",
};

export function Card({
  elevated = false,
  border = "hair",
  className = "",
  children,
  ...props
}: CardProps): JSX.Element {
  // base radius from the Fixed-Scale token (rounded-md = 7px, Phase 0); the
  // Plate Lift recipe lives in the `.card` CSS rule (styles.css) — `elevated`
  // applies that class so the shadow stays a single source of truth.
  const base = elevated
    ? "card"                       // bg-plate + border + radius + Plate Lift
    : `rounded-md bg-plate ${borderClass[border]}`;
  return (
    <div className={`${base} ${className}`} {...props}>
      {children}
    </div>
  );
}
// NOTE: when elevated, `.card` already sets bg/border/radius/shadow, so we
// drop borderClass to avoid double-borders; spec must reconcile `.card`'s
// hardcoded 12px radius + 0.5px hair border against the props above.
// `className` = PLACEMENT ONLY (margin, width, max-w, grid/flex position,
// overflow-hidden, sticky/fixed offsets). bg-*/border-*/shadow-*/rounded-*
// in a consumer className are banned by the guard.

// ─── IconButton ──────────────────────────────────────────────────
import type { ButtonHTMLAttributes } from "react";

type IconButtonTone = "ghost" | "danger";

interface IconButtonProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "aria-label"> {
  /** REQUIRED — icon-only buttons have no text; this is the accessible name. */
  label: string;
  /** hover intent. ghost → hover:text-ink (default); danger → hover:text-error
   *  (dismiss/remove/delete). */
  tone?: IconButtonTone;
  /** glyph or SVG. Omit + use `dismiss` for the standard × . */
  children?: React.ReactNode;
  /** convenience: render the canonical dismiss glyph (×) as children. */
  dismiss?: boolean;
}

const toneClass: Record<IconButtonTone, string> = {
  ghost: "text-ink-faint hover:text-ink",
  danger: "text-ink-faint hover:text-error",
};

export function IconButton({
  label,
  tone = "ghost",
  dismiss = false,
  className = "",
  children,
  type = "button",
  ...props
}: IconButtonProps): JSX.Element {
  return (
    <button
      type={type}
      aria-label={label}
      title={props.title ?? label}
      className={
        // >=44px touch target via min size; visible hit area stays compact via
        // inline-flex centering; canonical accent focus ring (PhasePanel:163).
        "inline-flex min-h-[44px] min-w-[44px] items-center justify-center " +
        "rounded leading-none transition-colors " +
        "focus-visible:outline focus-visible:outline-2 " +
        "focus-visible:outline-offset-2 focus-visible:outline-accent " +
        "disabled:cursor-not-allowed disabled:opacity-30 " +
        `${toneClass[tone]} ${className}`
      }
      {...props}
    >
      {dismiss ? "×" : children}
    </button>
  );
}
// `className` = PLACEMENT ONLY (margin, shrink-0, absolute offsets, hidden/
// xl:hidden). Text color / focus / hover utilities are owned by the primitive.
